import json
import os

def transform(grid):
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    # Group all non-zero cells by value
    value_cells = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                v = grid[r][c]
                if v not in value_cells:
                    value_cells[v] = []
                value_cells[v].append((r, c))

    # For each value, create L-shaped line
    for v in sorted(value_cells.keys()):
        cells = sorted(value_cells[v], key=lambda x: (x[0], x[1]))

        r_min = min(cell[0] for cell in cells)
        r_max = max(cell[0] for cell in cells)
        c_min = min(cell[1] for cell in cells)
        c_max = max(cell[1] for cell in cells)

        # L-shape rule
        if len(cells) == 1:
            # Single cell extends vertically to the bottom of the grid
            c = cells[0][1]
            for r in range(r_min, rows):
                result[r][c] = v
        else:
            # Multi-cell: L-shape from top cell to corner at (r_max, c_max)
            # Vertical from (r_min, c_min) down to (r_max, c_min)
            top_cell = cells[0]
            top_r, top_c = top_cell
            bottom_cell = cells[-1]
            bottom_r, bottom_c = bottom_cell

            for r in range(top_r, bottom_r + 1):
                result[r][top_c] = v

            # Horizontal from (top_c, bottom_r) to (bottom_c, bottom_r)
            if top_c < bottom_c:
                for c in range(top_c, bottom_c + 1):
                    result[bottom_r][c] = v
            elif top_c > bottom_c:
                for c in range(bottom_c, top_c + 1):
                    result[bottom_r][c] = v

    return result

